-- Run once in Supabase SQL Editor. Backend-only data, private image bucket.
BEGIN;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT INTO schema_migrations VALUES (1, to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS admins(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'admin', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, admin_id INTEGER REFERENCES admins(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS media_assets(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, storage_key TEXT UNIQUE NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT UNIQUE NOT NULL, slug TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slug TEXT UNIQUE, name TEXT NOT NULL, price_idr BIGINT, availability TEXT NOT NULL DEFAULT 'available' CHECK(availability IN ('available','unavailable')), description TEXT NOT NULL DEFAULT '', category_id INTEGER REFERENCES categories(id) ON DELETE RESTRICT, image_asset_id INTEGER REFERENCES media_assets(id), publication_status TEXT NOT NULL DEFAULT 'draft' CHECK(publication_status IN ('draft','published')), published_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(publication_status='draft' OR (length(name)>=3 AND price_idr IS NOT NULL AND price_idr BETWEEN 1 AND 999999999999 AND length(description)>=10 AND category_id IS NOT NULL AND image_asset_id IS NOT NULL AND slug IS NOT NULL AND published_at IS NOT NULL)));
CREATE INDEX IF NOT EXISTS product_public_date ON products(publication_status,published_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS product_public_price ON products(publication_status,price_idr,id);
CREATE INDEX IF NOT EXISTS product_category ON products(category_id,publication_status);
CREATE TABLE IF NOT EXISTS about_content(id INTEGER PRIMARY KEY CHECK(id=1), title TEXT NOT NULL, home_summary TEXT NOT NULL, description TEXT NOT NULL, image_asset_id INTEGER REFERENCES media_assets(id), image_alt TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contact_content(id INTEGER PRIMARY KEY CHECK(id=1), whatsapp TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', address TEXT NOT NULL, opening_hours TEXT NOT NULL, maps_url TEXT NOT NULL DEFAULT '', instagram_url TEXT NOT NULL DEFAULT '', facebook_url TEXT NOT NULL DEFAULT '', tiktok_url TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gallery_items(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, image_asset_id INTEGER NOT NULL REFERENCES media_assets(id), title TEXT NOT NULL, caption TEXT NOT NULL DEFAULT '', alt_text TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, is_published INTEGER NOT NULL DEFAULT 0 CHECK(is_published IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS gallery_order ON gallery_items(is_published,sort_order,id);
CREATE TABLE IF NOT EXISTS contact_links(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0);
INSERT INTO about_content VALUES (1,'Tentang TractorPart','[Placeholder] Profil toko belum tersedia. Informasi resmi TractorPart akan ditambahkan oleh pengelola.','[Placeholder] Deskripsi toko belum diisi. Silakan perbarui profil, layanan, dan informasi toko melalui halaman admin.',NULL,'',to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ON CONFLICT DO NOTHING;
INSERT INTO contact_content (id,address,opening_hours,updated_at) VALUES (1,'[Placeholder] Alamat toko belum diisi','[Placeholder] Jam operasional belum diisi',to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ON CONFLICT DO NOTHING;

ALTER TABLE public.schema_migrations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.schema_migrations FROM anon, authenticated;
ALTER TABLE public.admins ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.admins FROM anon, authenticated;
ALTER TABLE public.sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.sessions FROM anon, authenticated;
ALTER TABLE public.login_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.login_attempts FROM anon, authenticated;
ALTER TABLE public.media_assets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.media_assets FROM anon, authenticated;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.categories FROM anon, authenticated;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.products FROM anon, authenticated;
ALTER TABLE public.about_content ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.about_content FROM anon, authenticated;
ALTER TABLE public.contact_content ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.contact_content FROM anon, authenticated;
ALTER TABLE public.gallery_items ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.gallery_items FROM anon, authenticated;
ALTER TABLE public.contact_links ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.contact_links FROM anon, authenticated;
REVOKE ALL ON SEQUENCE public.admins_id_seq FROM anon, authenticated;
REVOKE ALL ON SEQUENCE public.media_assets_id_seq FROM anon, authenticated;
REVOKE ALL ON SEQUENCE public.categories_id_seq FROM anon, authenticated;
REVOKE ALL ON SEQUENCE public.products_id_seq FROM anon, authenticated;
REVOKE ALL ON SEQUENCE public.gallery_items_id_seq FROM anon, authenticated;
REVOKE ALL ON SEQUENCE public.contact_links_id_seq FROM anon, authenticated;
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
VALUES ('tractorpart-media','tractorpart-media',false,5242880,ARRAY['image/webp'])
ON CONFLICT(id) DO UPDATE SET public=false,file_size_limit=5242880,allowed_mime_types=ARRAY['image/webp'];
-- No anonymous Storage policy: Express authorizes /media/:id before retrieving objects.
COMMIT;
